package com.ruoyi.ai.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.ruoyi.ai.dto.AiConversationPolicyRequest;import com.ruoyi.ai.mapper.AiConversationMaintenanceMapper;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.common.utils.SecurityUtils;import com.ruoyi.common.utils.StringUtils;import com.ruoyi.system.domain.SysConfig;import com.ruoyi.system.service.ISysConfigService;@Service public class AiConversationPolicyService{public static final String RETENTION="ai.conversation.retentionDays",ARCHIVE="ai.conversation.userArchiveEnabled",DELETE="ai.conversation.userDeleteEnabled";private final ISysConfigService configs;private final AiConversationMaintenanceMapper maintenance;public AiConversationPolicyService(ISysConfigService c,AiConversationMaintenanceMapper m){configs=c;maintenance=m;}public Map<String,Object> view(){Map<String,Object>v=new LinkedHashMap<>();v.put("retentionDays",retentionDays());v.put("userArchiveEnabled",userArchiveEnabled());v.put("userDeleteEnabled",userDeleteEnabled());v.put("cleanupMode","DAILY_03_20_AND_MANUAL");return v;}public int retentionDays(){String v=configs.selectConfigByKey(RETENTION);try{return Math.max(1,Math.min(3650,Integer.parseInt(v)));}catch(Exception e){return 90;}}public boolean userArchiveEnabled(){return bool(ARCHIVE,true);}public boolean userDeleteEnabled(){return bool(DELETE,false);}public Map<String,Object> save(AiConversationPolicyRequest r){if(r==null)throw new ServiceException("策略不能为空");if(r.getRetentionDays()!=null){if(r.getRetentionDays()<1||r.getRetentionDays()>3650)throw new ServiceException("会话保留天数必须在 1-3650 之间");upsert(RETENTION,"AI 会话保留天数",String.valueOf(r.getRetentionDays()),"超过保留期且无活动 Run 的会话由 AI 清理任务物理清理");}if(r.getUserArchiveEnabled()!=null)upsert(ARCHIVE,"AI 用户允许归档会话",String.valueOf(r.getUserArchiveEnabled()),"用户是否可将自己的会话归档");if(r.getUserDeleteEnabled()!=null)upsert(DELETE,"AI 用户允许删除会话",String.valueOf(r.getUserDeleteEnabled()),"用户删除为软删除；到保留期后由系统物理清理");return view();}@Transactional public int cleanupExpired(){List<Long>ids=maintenance.selectExpiredIds(retentionDays());for(Long id:ids){maintenance.deletePending(id);maintenance.deleteCheckpoints(id);maintenance.deleteMessages(id);maintenance.deleteRuns(id);maintenance.deleteConversation(id);}return ids.size();}private boolean bool(String k,boolean d){String v=configs.selectConfigByKey(k);return StringUtils.isBlank(v)?d:Boolean.parseBoolean(v);}private void upsert(String key,String name,String value,String remark){SysConfig q=new SysConfig();q.setConfigKey(key);List<SysConfig>rows=configs.selectConfigList(q);SysConfig c=rows.isEmpty()?new SysConfig():rows.get(0);c.setConfigName(name);c.setConfigKey(key);c.setConfigValue(value);c.setConfigType("Y");c.setRemark(remark);if(c.getConfigId()==null){c.setCreateBy(SecurityUtils.getUsername());configs.insertConfig(c);}else{c.setUpdateBy(SecurityUtils.getUsername());configs.updateConfig(c);}}}
